CREATE COLUMN TABLE "TEST_AP"."OTPL" ("TplNum" INTEGER CS_INT NOT NULL , "TplName" NVARCHAR(100), "TplType" NVARCHAR(3) NOT NULL , "TplCode" NVARCHAR(20) NOT NULL , PRIMARY KEY ("TplNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTPL_CODE" ON "TEST_AP"."OTPL" ( "TplCode" ASC, "TplType" ASC )